import pytest
import jsonschema
from jsonschema import validate


class TestFixEndpoint:
    """Test suite for /api/data/fix endpoint"""
    
    # JSON Schema for 200 response validation
    SUCCESS_SCHEMA = {
        "type": "array",
        "items": {
            "type": "object",
            "properties": {
                "id": {"type": "string"},
                "type": {"type": "string"},
                "lat": {"type": "number"},
                "lon": {"type": "number"}
            },
            "required": ["id", "lat", "lon"]
        }
    }
    
    # JSON Schema for 400 response validation
    ERROR_SCHEMA = {
        "type": "object",
        "properties": {
            "status": {"type": "string"},
            "error": {"type": "string"}
        }
    }

    @pytest.mark.parametrize("test_id,params,expected_status", [
        # Happy path scenarios
        ("no_params", {}, 200),
        ("single_fix_id", {"ids": "BARBQ"}, 200),
        ("bbox_only", {"bbox": "40,-90,45,-85"}, 200),
        ("format_raw", {"format": "raw"}, 200),
        ("multiple_params", {"ids": "BARBQ", "bbox": "40,-90,45,-85", "format": "raw"}, 200),
        
        # Edge cases and boundary conditions
        ("empty_ids", {"ids": ""}, 200),
        ("empty_bbox", {"bbox": ""}, 200),
        ("different_format", {"format": "json"}, 200),
        
        # Error scenarios (assuming these would trigger 400)
        ("invalid_bbox_format", {"bbox": "invalid_format"}, 400),
        ("malformed_bbox", {"bbox": "40,-90,45"}, 400),
        ("out_of_range_bbox", {"bbox": "-100,-200,100,200"}, 400),
    ])
    def test_fix_endpoint_parameterized(self, api_client, test_id, params, expected_status):
        """Test /api/data/fix endpoint with various parameter combinations"""
        response = api_client.get("/api/data/fix", params=params)
        
        assert response.status_code == expected_status, \
            f"Expected status {expected_status}, got {response.status_code} for test: {test_id}"
        
        if expected_status == 200:
            assert response.headers['Content-Type'] == 'application/json'
            data = response.json()
            
            # Validate response schema
            try:
                validate(instance=data, schema=self.SUCCESS_SCHEMA)
            except jsonschema.ValidationError as e:
                pytest.fail(f"Response schema validation failed: {e}")
            
            # Additional validation for successful responses
            if data:  # If we got data back
                for item in data:
                    assert 'id' in item
                    assert 'lat' in item
                    assert 'lon' in item
                    assert isinstance(item['id'], str)
                    assert isinstance(item['lat'], (int, float))
                    assert isinstance(item['lon'], (int, float))
        
        elif expected_status == 400:
            # For error responses, validate error schema
            content_type = response.headers.get('Content-Type', '')
            if 'application/json' in content_type:
                data = response.json()
                try:
                    validate(instance=data, schema=self.ERROR_SCHEMA)
                except jsonschema.ValidationError:
                    # Some flexibility for error response format
                    pass

    def test_fix_endpoint_success_with_specific_fix(self, api_client):
        """Test successful retrieval of specific fix data"""
        params = {"ids": "BARBQ"}
        response = api_client.get("/api/data/fix", params=params)
        
        assert response.status_code == 200
        data = response.json()
        
        # If we get data for BARBQ, validate its structure
        if data:
            barbq_fix = next((item for item in data if item.get('id') == 'BARBQ'), None)
            if barbq_fix:
                assert barbq_fix['type'] == 'I'
                assert barbq_fix['lat'] == pytest.approx(39.0811, abs=0.001)
                assert barbq_fix['lon'] == pytest.approx(-94.7681, abs=0.001)

    def test_fix_endpoint_bbox_functionality(self, api_client):
        """Test bounding box parameter functionality"""
        params = {"bbox": "40,-90,45,-85"}  # Chicago area
        response = api_client.get("/api/data/fix", params=params)
        
        assert response.status_code == 200
        data = response.json()
        
        # Validate that returned fixes are within the bounding box
        if data:
            for fix in data:
                lat = fix['lat']
                lon = fix['lon']
                assert 40 <= lat <= 45, f"Latitude {lat} outside bbox range"
                assert -90 <= lon <= -85, f"Longitude {lon} outside bbox range"

    def test_fix_endpoint_response_structure(self, api_client):
        """Test that response structure matches OpenAPI specification"""
