    def test_fix_endpoint_performance(self, api_client):
        """Test endpoint performance with reasonable timeout"""
        import time
        start_time = time.time()
        
        response = api_client.get("/api/data/fix")
        
        end_time = time.time()
        response_time = end_time - start_time
        
